import { useEffect } from "react";

import { useTextarea } from "./use-textarea";

export const useAriaDescribedBy = ({
  id,
  "aria-hidden": ariaHidden,
}: {
  id: string;
  "aria-hidden"?: boolean;
}) => {
  const { addAriaDescribedBy, removeAriaDescribedBy } = useTextarea();

  useEffect(() => {
    if (!ariaHidden) {
      addAriaDescribedBy(id);
    }
    return () => {
      removeAriaDescribedBy(id);
    };
  }, [addAriaDescribedBy, removeAriaDescribedBy, id, ariaHidden]);
};
